    extends BaseTokenizer[TemporalValue] {

  import TemporalValue._

  def tokenize(value: TemporalValue): Token = {
    val fmt = formatStr match {
      case Some(f) => f
      case None => value match {
        case _: DateTimeValue => TemporalTokenizer.IsoFormat
        case _: DateValue     => TemporalTokenizer.DateFormat
      }
