// Complex Nested Generics
// ============================================================================

/** Registry with complex nested generic types.
  *
  * Manages named containers and a chain of handler functions.
  */
class TokenRegistry[A] {
  private val registry = mutable.Map.empty[String, TokenContainer[A]]
  private val handlers = mutable.ListBuffer.empty[A => Option[Token]]

  def register(key: String, container: TokenContainer[A]): Unit =
    registry(key) = container

  def addHandler(handler: A => Option[Token]): Unit =
    handlers += handler

  /** Process all items in a container through all handlers. */
  def process(key: String): List[Option[Token]] = {
    registry.get(key) match {
      case None => Nil
      case Some(container) =>
        container.getAll.map { item =>
          handlers.iterator
            .map(h => h(item))
            .collectFirst { case some @ Some(_) => some }
            .flatten
        }.toList
    }
  }
}

