/** Tokenizer for JSON structures with recursive types.
  *
  * Uses Scala's native JSON-like representation with Any and pattern matching
  * for recursive traversal.
  */
class JsonTokenizer(pretty: Boolean = false) {

  /** Serialize a JSON-like value to a JSON string. */
  private def toJsonString(value: Any): String = value match {
    case null          => "null"
    case s: String     => "\"" + escapeJson(s) + "\""
    case b: Boolean    => b.toString
    case n: Int        => n.toString
    case n: Long       => n.toString
    case n: Double     => if (n.isWhole) n.toLong.toString else n.toString
    case n: BigDecimal => n.toString
    case xs: Seq[_]    => xs.map(toJsonString).mkString("[", ", ", "]")
    case xs: List[_]   => xs.map(toJsonString).mkString("[", ", ", "]")
    case m: Map[_, _] =>
      m.map { case (k, v) => s"\"$k\": ${toJsonString(v)}" }
        .mkString("{", ", ", "}")
    case other => "\"" + escapeJson(other.toString) + "\""
  }

  private def toPrettyJsonString(value: Any, indent: Int = 0): String = {
    val pad = "  " * indent
    val padInner = "  " * (indent + 1)
    value match {
      case null          => "null"
      case s: String     => "\"" + escapeJson(s) + "\""
      case b: Boolean    => b.toString
      case n: Int        => n.toString
      case n: Long       => n.toString
      case n: Double     => if (n.isWhole) n.toLong.toString else n.toString
      case n: BigDecimal => n.toString
      case xs: Seq[_] if xs.isEmpty => "[]"
      case xs: Seq[_] =>
        xs.map(x => padInner + toPrettyJsonString(x, indent + 1))
          .mkString("[\n", ",\n", "\n" + pad + "]")
      case xs: List[_] if xs.isEmpty => "[]"
      case xs: List[_] =>
        xs.map(x => padInner + toPrettyJsonString(x, indent + 1))
          .mkString("[\n", ",\n", "\n" + pad + "]")
      case m: Map[_, _] if m.isEmpty => "{}"
      case m: Map[_, _] =>
        m.map { case (k, v) =>
            s"""$padInner"$k": ${toPrettyJsonString(v, indent + 1)}"""
          }
          .mkString("{\n", ",\n", "\n" + pad + "}")
      case other => "\"" + escapeJson(other.toString) + "\""
    }
  }

  private def escapeJson(s: String): String =
    s.replace("\\", "\\\\")
      .replace("\"", "\\\"")
      .replace("\n", "\\n")
      .replace("\r", "\\r")
      .replace("\t", "\\t")

  def tokenize(value: Any): Token = {
    val jsonStr = if (pretty) toPrettyJsonString(value) else toJsonString(value)
    Token(jsonStr, TokenType.Structured, Map("json" -> true))
  }

  /** Extract and tokenize a value at a dot-separated JSON path. */
  def tokenizePath(value: Any, path: String): Option[Token] = {
    val parts = path.split("\\.")

    val result = parts.foldLeft(Option(value)) {
      case (None, _) => None
      case (Some(current), part) =>
        current match {
          case m: Map[_, _] =>
            m.asInstanceOf[Map[String, Any]].get(part)
          case xs: Seq[_] =>
            Try(part.toInt).toOption.filter(i => i >= 0 && i < xs.size).map(xs(_))
          case xs: List[_] =>
            Try(part.toInt).toOption.filter(i => i >= 0 && i < xs.size).map(xs(_))
          case _ => None
        }
    }

    result.map(tokenize)
