// Builder Pattern with Fluent Interface
// ============================================================================

/** Fluent builder for creating tokenizers.
  *
  * Uses method chaining with generic return types.
  */
class TokenizerBuilder[A] {
  private var normalizers: List[String => String]  = Nil
  private var validators: List[A => Boolean]       = Nil
  private var _metadata: Map[String, Any]          = Map.empty

  def withNormalizer(normalizer: String => String): TokenizerBuilder[A] = {
    normalizers = normalizers :+ normalizer
    this
  }

  def withValidator(validator: A => Boolean): TokenizerBuilder[A] = {
    validators = validators :+ validator
    this
  }

  def withMetadata(entries: (String, Any)*): TokenizerBuilder[A] = {
    _metadata = _metadata ++ entries.toMap
    this
  }

  /** Build the final tokenizer function. */
  def build(): A => Token = {
    val ns = normalizers
    val vs = validators
    val md = _metadata

    value => {
      vs.foreach { validator =>
        if (!validator(value))
          throw new IllegalArgumentException(s"Validation failed for $value")
      }

      var strValue = value.toString
      ns.foreach { normalizer =>
        strValue = normalizer(strValue)
      }

      Token(strValue, TokenType.String, md)
    }
  }
}

