    _processed = true
  }
}

// ============================================================================
// Generic Container Classes
// ============================================================================

/** Covariant container — can return subtypes. */
class TokenContainer[+A](items: Seq[A]) {
  private val _items: Seq[A] = items

  def getAll: Seq[A] = _items

  def mapTokens(f: A => String): List[String] =
    _items.map(f).toList
}

/** Contravariant sink — can accept supertypes. */
class TokenSink[-A] {
  private val _received = mutable.ListBuffer.empty[Any]

  def receive(item: A): Unit =
    _received += item

  def drain(): List[Any] = {
    val result = _received.toList
    _received.clear()
    result
  }
}

/** Invariant handler — exact type matching required. */
class BivariantHandler[A](private var _value: A) {

  def get: A = _value

  def set(value: A): Unit = {
    _value = value
  }

  def transform(f: A => A): A = {
    _value = f(_value)
    _value
  }
}

// ============================================================================
// Tokenizer Implementations
// ============================================================================

/** Abstract base tokenizer with generic input type. */
trait BaseTokenizer[A] {

  /** Convert value to token. */
  def tokenize(value: A): Token

  /** Lazy tokenization of multiple values. */
  def tokenizeBatch(values: Iterable[A]): Iterator[Token] =
    values.iterator.map(tokenize)
}

/** Tokenizer for string and bytes types.
  *
  * In Scala, bytes are represented as Array[Byte]. We use Either
  * to express the str-or-bytes union from Python.
  */
class StringTokenizer(
    encoding: String = "UTF-8",
    normalizer: String => String = identity
) extends BaseTokenizer[Either[Array[Byte], String]] {

  def tokenize(value: Either[Array[Byte], String]): Token = {
    val strValue = value match {
      case Left(bytes)  => new String(bytes, encoding)
      case Right(str)   => str
    }
    val normalized = normalizer(strValue)
    Token(normalized, TokenType.String)
  }
}

/** Sealed ADT representing numeric input values, replacing Python's NumericT TypeVar. */
sealed trait NumericValue
object NumericValue {
  case class IntValue(v: Int)           extends NumericValue
  case class DoubleValue(v: Double)     extends NumericValue
  case class DecimalValue(v: BigDecimal) extends NumericValue
}

/** Tokenizer for numeric types with precision handling. */
class NumericTokenizer(
    precision: Int = 6,
    formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[NumericValue] {

  import NumericValue._

  def tokenize(value: NumericValue): Token = {
    val (strValue, originalType) = value match {
      case DecimalValue(v) => (s"%,.${precision}f".format(v) .replace(",", ""), "BigDecimal")
      case DoubleValue(v)  => (s"%.${precision}f".format(v), "Double")
      case IntValue(v)     => (v.toString, "Int")
    }
    Token(strValue, TokenType.Numeric, Map("original_type" -> originalType))
  }
}

/** Sealed ADT representing temporal input values. */
sealed trait TemporalValue
object TemporalValue {
  case class DateTimeValue(v: LocalDateTime) extends TemporalValue
  case class DateValue(v: LocalDate)         extends TemporalValue
}

/** Tokenizer for date/time types. */
class TemporalTokenizer(formatStr: Option[String] = None)
    extends BaseTokenizer[TemporalValue] {

  import TemporalValue._

  def tokenize(value: TemporalValue): Token = {
    val fmt = formatStr match {
      case Some(f) => f
      case None => value match {
        case _: DateTimeValue => TemporalTokenizer.IsoFormat
        case _: DateValue     => TemporalTokenizer.DateFormat
      }
    }
    val formatter = DateTimeFormatter.ofPattern(fmt)
    val formatted = value match {
      case DateTimeValue(v) => v.format(formatter)
      case DateValue(v)     => v.format(formatter)
    }
    Token(formatted, TokenType.Temporal)
  }
}

object TemporalTokenizer {
  val IsoFormat: String  = "yyyy-MM-dd'T'HH:mm:ss"
  val DateFormat: String = "yyyy-MM-dd"
}

// ============================================================================
// Advanced: Union Types and Overloads
// ============================================================================

/** Tokenizer that handles multiple types via pattern matching dispatch. */
class UniversalTokenizer {
  private val stringTokenizer  = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  /** Dispatch to appropriate tokenizer based on runtime type. */
  def tokenize(value: Any): Token = value match {
    case null =>
      Token("NULL", TokenType.Null)
    case t: Tokenizable =>
      Token(t.toToken, TokenType.Structured)
    case s: String =>
      stringTokenizer.tokenize(Right(s))
    case b: Array[Byte] =>
      stringTokenizer.tokenize(Left(b))
    case i: Int =>
      numericTokenizer.tokenize(NumericValue.IntValue(i))
    case d: Double =>
      numericTokenizer.tokenize(NumericValue.DoubleValue(d))
    case bd: BigDecimal =>
      numericTokenizer.tokenize(NumericValue.DecimalValue(bd))
    case dt: LocalDateTime =>
      temporalTokenizer.tokenize(TemporalValue.DateTimeValue(dt))
    case d: LocalDate =>
      temporalTokenizer.tokenize(TemporalValue.DateValue(d))
    case other =>
      Token(other.toString, TokenType.String, Map("fallback" -> true))
  }
}

// ============================================================================
// Complex Nested Generics
// ============================================================================

/** Registry with complex nested generic types.
  *
  * Manages named containers and a chain of handler functions.
  */
class TokenRegistry[A] {
  private val registry = mutable.Map.empty[String, TokenContainer[A]]
  private val handlers = mutable.ListBuffer.empty[A => Option[Token]]

  def register(key: String, container: TokenContainer[A]): Unit =
    registry(key) = container

  def addHandler(handler: A => Option[Token]): Unit =
    handlers += handler

  /** Process all items in a container through all handlers. */
  def process(key: String): List[Option[Token]] = {
    registry.get(key) match {
      case None => Nil
      case Some(container) =>
        container.getAll.map { item =>
          handlers.iterator
            .map(h => h(item))
            .collectFirst { case some @ Some(_) => some }
            .flatten
        }.toList
    }
  }
}

// ============================================================================
// Higher-Kinded Type Simulation → Proper Functor / Monad
// ============================================================================

/** Functor wrapper for tokens. */
class TokenFunctor[A](protected val _value: A) {

  def map[B](f: A => B): TokenFunctor[B] =
    new TokenFunctor(f(_value))

  def flatMap[B](f: A => TokenFunctor[B]): TokenFunctor[B] =
    f(_value)

  def getOrElse[B >: A](default: => B): B =
    if (_value != null) _value else default
}

/** Extended monad operations. */
class TokenMonad[A](value: A) extends TokenFunctor[A](value) {

  def ap[B](funcWrapped: TokenMonad[A => B]): TokenMonad[B] =
    new TokenMonad(funcWrapped._value(_value))
}

object TokenMonad {
  def pure[A](value: A): TokenMonad[A] = new TokenMonad(value)
}

// ============================================================================
// JSON Structure Tokenization
// ============================================================================

/** Tokenizer for JSON structures with recursive types.
  *
  * Uses Scala's native JSON-like representation with Any and pattern matching
  * for recursive traversal.
  */
class JsonTokenizer(pretty: Boolean = false) {

  /** Serialize a JSON-like value to a JSON string. */
  private def toJsonString(value: Any): String = value match {
    case null          => "null"
    case s: String     => "\"" + escapeJson(s) + "\""
    case b: Boolean    => b.toString
    case n: Int        => n.toString
    case n: Long       => n.toString
    case n: Double     => if (n.isWhole) n.toLong.toString else n.toString
    case n: BigDecimal => n.toString
    case xs: Seq[_]    => xs.map(toJsonString).mkString("[", ", ", "]")
    case m: Map[_, _] =>
      m.map { case (k, v) => s"\"$k\": ${toJsonString(v)}" }
        .mkString("{", ", ", "}")
    case other => "\"" + escapeJson(other.toString) + "\""
  }

  private def toPrettyJsonString(value: Any, indent: Int = 0): String = {
    val pad = "  " * indent
    val padInner = "  " * (indent + 1)
    value match {
      case null          => "null"
      case s: String     => "\"" + escapeJson(s) + "\""
      case b: Boolean    => b.toString
      case n: Int        => n.toString
      case n: Long       => n.toString
      case n: Double     => if (n.isWhole) n.toLong.toString else n.toString
      case n: BigDecimal => n.toString
      case xs: Seq[_] if xs.isEmpty => "[]"
      case xs: Seq[_] =>
        xs.map(x => padInner + toPrettyJsonString(x, indent + 1))
          .mkString("[\n", ",\n", "\n" + pad + "]")
      case m: Map[_, _] if m.isEmpty => "{}"
      case m: Map[_, _] =>
        m.map { case (k, v) =>
            s"""$padInner"$k": ${toPrettyJsonString(v, indent + 1)}"""
          }
          .mkString("{\n", ",\n", "\n" + pad + "}")
      case other => "\"" + escapeJson(other.toString) + "\""
    }
  }

  private def escapeJson(s: String): String =
    s.replace("\\", "\\\\")
      .replace("\"", "\\\"")
      .replace("\n", "\\n")
      .replace("\r", "\\r")
      .replace("\t", "\\t")

  def tokenize(value: Any): Token = {
    val jsonStr = if (pretty) toPrettyJsonString(value) else toJsonString(value)
    Token(jsonStr, TokenType.Structured, Map("json" -> true))
  }

  /** Extract and tokenize a value at a dot-separated JSON path. */
  def tokenizePath(value: Any, path: String): Option[Token] = {
    val parts = path.split("\\.")

    val result = parts.foldLeft(Option(value)) {
      case (None, _) => None
      case (Some(current), part) =>
        current match {
          case m: Map[_, _] =>
            m.asInstanceOf[Map[String, Any]].get(part)
          case xs: Seq[_] =>
            Try(part.toInt).toOption.filter(i => i >= 0 && i < xs.size).map(xs(_))
          case _ => None
        }
    }

    result.map(tokenize)
  }
}

// ============================================================================
// Whitespace Tokenizer - Basic Text Tokenization
// ============================================================================

/** Basic tokenizer that splits text by whitespace.
  *
  * A fundamental tokenization operation used in NLP and text processing.
  */
class WhitespaceTokenizer(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
) {

  private val punctuation: Set[Char] =
    Set('.', ',', '!', '?', ';', ':', '\'', '"', '(', ')', '[', ']', '{', '}')

  /** Process a single word into a token string. */
  private def processToken(word: String): Option[String] = {
    var w = word

    if (stripPunctuation)
      w = w.dropWhile(punctuation.contains).reverse.dropWhile(punctuation.contains).reverse

    if (lowercase)
      w = w.toLowerCase

    if (w.length < minLength)
      return None

    maxLength.foreach { max =>
      if (w.length > max)
        w = w.take(max)
    }

    if (w.nonEmpty) Some(w) else None
  }

  /** Split text by whitespace and return list of tokens. */
  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+").filter(_.nonEmpty)
    words.zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map { processed =>
        Token(
          value = processed,
          tokenType = TokenType.String,
          metadata = Map("position" -> i, "original" -> word)
        )
      }
    }.toList
  }

  /** Split text by whitespace and return list of token strings. */
  def tokenizeToStrings(text: String): List[String] =
    tokenize(text).map(_.value)

  /** Tokenize text and return tokens with character positions. */
  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val result = mutable.ListBuffer.empty[(String, Int, Int)]
    var currentPos = 0

    for (word <- text.split("\\s+").filter(_.nonEmpty)) {
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      processToken(word).foreach { processed =>
        result += ((processed, start, end))
      }

      currentPos = end
    }

    result.toList
  }

  /** Return the number of tokens in the text. */
  def countTokens(text: String): Int =
    tokenize(text).size
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

/** Fluent builder for creating tokenizers.
  *
  * Uses method chaining with generic return types.
  */
class TokenizerBuilder[A] {
  private var normalizers: List[String => String]  = Nil
  private var validators: List[A => Boolean]       = Nil
  private var _metadata: Map[String, Any]          = Map.empty

  def withNormalizer(normalizer: String => String): TokenizerBuilder[A] = {
    normalizers = normalizers :+ normalizer
    this
  }

  def withValidator(validator: A => Boolean): TokenizerBuilder[A] = {
    validators = validators :+ validator
    this
  }

  def withMetadata(entries: (String, Any)*): TokenizerBuilder[A] = {
    _metadata = _metadata ++ entries.toMap
    this
  }

  /** Build the final tokenizer function. */
  def build(): A => Token = {
    val ns = normalizers
    val vs = validators
    val md = _metadata

    value => {
      vs.foreach { validator =>
        if (!validator(value))
          throw new IllegalArgumentException(s"Validation failed for $value")
      }

      var strValue = value.toString
      ns.foreach { normalizer =>
        strValue = normalizer(strValue)
      }

      Token(strValue, TokenType.String, md)
    }
  }
}
